/**
 * Rewrites one subject's document. A subject that is gone or archived is
 * removed, so a reindex request cannot put it back.
 */
async function reindexSubject(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  switch (subjectKind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(orgId, subjectId as Issue["id"]);
      if (issue === null || isArchived(issue)) {
        await removeFromIndex(orgId, "issue", subjectId);
        return;
      }
      await indexIssue(orgId, issue);
      return;
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as Comment["id"],
      );
      if (comment === null || isArchived(comment)) {
        await removeFromIndex(orgId, "comment", subjectId);
        return;
      }
      await indexComment(orgId, comment);
      return;
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        subjectId as Project["id"],
      );
      if (project === null || isArchived(project)) {
        await removeFromIndex(orgId, "project", subjectId);
        return;
      }
      await indexProject(orgId, project);
      return;
    }
  }
}

function hrefFor(kind: SearchSubjectKind, subjectId: string): string {

  const updated = await commentRepo.updateComment(input);

  await emit("search.reindex_requested", {
    ...actorEnvelope(actor),
    subjectKind: "comment",
    subjectId: updated.id,
  });

  return updated;
}

