const debounced = useDebouncedValue(raw);
const advanced =
  flags.advanced_search === true ||
  isEnabled("advanced_search", { ...ANONYMOUS_FLAG_CONTEXT, orgId });
const parsed = parseSearchQuery(debounced, advanced);

// The request carries the raw query. The service runs this same parser, so
// the hint and the hits describe one interpretation.
const pending = debounced.length > 0 && results.query !== debounced;

useEffect(() => {
  if (!open || debounced.length === 0) return;

  let cancelled = false;
  const understood = parseSearchQuery(debounced, advanced);

  void onSearch({
    orgId,
    q: debounced,
    kinds: [...understood.kinds],
    ...(understood.projectId !== null
      ? { projectId: understood.projectId }
      : {}),
    limit: SEARCH_PAGE_SIZE,
  }).then((result) => {
    if (cancelled) return;
    setResults({ query: debounced, hits: result.ok ? result.data : [] });
  });

  return () => {
    cancelled = true;
  };
}, [open, orgId, onSearch, debounced, advanced]);

